var REGULATIONS = [{"code":"1.71","topic":"delta","about":"What the Delta legally is","title":"Sacramento-San Joaquin River Delta","text":"Sacramento-San Joaquin River Delta The Sacramento-San Joaquin River Delta includes all rivers, sloughs, canals, cuts, forebays, and flooded islands within the area south of Interstate 80 to its junction with Highway 50, and south of Highway 50 via the Pioneer Bridge to its junction with Highway 99, west of Highway 99, north of Interstate 580, 205, and Highway 120, and east of Interstate 680.","parts":[],"deep":false,"source":"CCR Title 14"},{"code":"2.10(c)(1)","topic":"delta","about":"Hook gaps in the Delta","title":"Hook And Weight Restrictions","text":"No person shall use any single hook with a gap greater than 1 inch or any multiple hook with a gap greater than 3/4 inch.","parts":[],"deep":false,"source":"CCR Title 14"},{"code":"2.25(b)(1)","topic":"delta","about":"Bow and arrow fishing in the Delta","title":"Bow and Arrow Fishing","text":"Within the boundaries of the Sacramento-San Joaquin River Delta (See Section1.71)","parts":[],"deep":false,"source":"CCR Title 14"},{"code":"5.00(a)(1)","topic":"bass","about":"Black bass: lakes, reservoirs and the Delta","title":"Black Bass","text":"Lakes/Reservoirs and the Sacramento-San Joaquin Delta: The following waters, except for those listed in subsection (b), are open to fishing all year, with a 12-inch total length minimum size limit and a five-fish daily bag limit: All lakes and reservoirs in the State, and the Sacramento-San Joaquin River Delta, (see Section 1.71 for definition of the Delta).","parts":[],"deep":false,"source":"CCR Title 14"},{"code":"5.75(a)","topic":"striper","about":"Striped bass: open season","title":"Striped Bass","text":"Open season: All year except for closures listed in special regulations.","parts":[],"deep":false,"source":"CCR Title 14"},{"code":"5.75(b)","topic":"striper","about":"Striped bass: limit","title":"Striped Bass","text":"Limit: Two, except in waters listed in (d) below.","parts":[],"deep":false,"source":"CCR Title 14"},{"code":"5.75(c)","topic":"striper","about":"Striped bass: minimum size","title":"Striped Bass","text":"Minimum size: 18 inches total length except in waters listed in (d) below.","parts":[],"deep":false,"source":"CCR Title 14"},{"code":"5.75(d)","topic":"striper","about":"Striped bass: where the limit and the size are different","title":"Striped Bass","text":"Exceptions:","parts":[{"code":"5.75(d)(1)","text":"In the Colorado River District, the Southern District, and New Hogan, San Antonio and Santa Margarita lakes","kids":2},{"code":"5.75(d)(1)(A)","text":"Limit: Ten.","kids":0},{"code":"5.75(d)(1)(B)","text":"Minimum size: No size limit.","kids":0}],"deep":true,"source":"CCR Title 14"},{"code":"5.75(e)","topic":"striper","about":"Striped bass: hybrids","title":"Striped Bass","text":"For the purpose of these regulations, any striped bass hybrid with white bass is considered to be striped bass.","parts":[],"deep":false,"source":"CCR Title 14"},{"code":"5.80(a)","topic":"sturgeon","about":"White sturgeon: open season","title":"Inland White Sturgeon","text":"Open season:","parts":[{"code":"5.80(a)(1)","text":"From October 1 through June 30: from the west Carquinez Bridge east to downstream of the confluence of the Feather River on the Sacramento River and downstream of the I-5 bridge on the San Joaquin River","kids":0},{"code":"5.80(a)(2)","text":"From October 1 through December 31: upstream of the confluence of the Feather River to the Highway 162 Bridge on the Sacramento River and upstream of the I-5 bridge on the San Joaquin River.","kids":0},{"code":"5.80(a)(3)","text":"Year-round: all tributaries of the Sacramento and San Joaquin Rivers are closed.","kids":0}],"deep":true,"source":"CCR Title 14"},{"code":"5.80(b)","topic":"sturgeon","about":"White sturgeon: daily limit","title":"Inland White Sturgeon","text":"Daily limit: Zero fish.","parts":[],"deep":false,"source":"CCR Title 14"},{"code":"5.80(c)","topic":"sturgeon","about":"White sturgeon: annual limit","title":"Inland White Sturgeon","text":"Annual bag limit: zero fish per calendar year statewide.","parts":[],"deep":false,"source":"CCR Title 14"},{"code":"5.80(d)","topic":"sturgeon","about":"White sturgeon: methods of take","title":"Inland White Sturgeon","text":"Methods of take: Only one single point, single shank, barbless hook shall be used on a line when taking sturgeon. The sturgeon must voluntarily take the bait or lure inside its mouth. No sturgeon may be taken by trolling, snagging or by the use of firearms. Sturgeon may not be gaffed, nor shall any person use any type of firearm or snare to take any sturgeon. For the purposes of this section, a snare is a flexible loop made from any material that can be tightened like a noose around any part of the fish.","parts":[],"deep":false,"source":"CCR Title 14"},{"code":"5.80(e)","topic":"sturgeon","about":"White sturgeon: handling and removal from water","title":"Inland White Sturgeon","text":"Handling and removal from water. Any sturgeon greater than 60 inches fork length may not be removed from the water and shall be released immediately. Sturgeon of any size shall not be held out of water suspended by the gills, gill plates, mouth, or solely by the tail, and shall not be dragged across the ground, boat decks, or piers. Lip gripper devices shall not be used on sturgeon.","parts":[],"deep":false,"source":"CCR Title 14"},{"code":"5.80(f)","topic":"sturgeon","about":"White sturgeon: report card required","title":"Inland White Sturgeon","text":"Sturgeon Fishing Report Card Required: All anglers must have a valid Sturgeon Fishing Report Card in their possession while fishing for white sturgeon. Anglers must complete and return the report card pursuant to regulations in this Section and Section 1.74.","parts":[],"deep":false,"source":"CCR Title 14"},{"code":"5.80(i)","topic":"sturgeon","about":"Sturgeon closure, Sierra and Valley District","title":"Inland White Sturgeon","text":"Special Sierra and Valley District Sturgeon Closure from January 1 to December 31 (Shasta, Tehama, Butte and Glenn cos)","parts":[{"code":"5.80(i)(1)","text":"Sacramento River from Keswick Dam to the Highway 162 Bridge.","kids":3},{"code":"5.80(i)(1)(A)","text":"It is unlawful to take any sturgeon.","kids":0},{"code":"5.80(i)(1)(B)","text":"It is unlawful to use wire leaders.","kids":0},{"code":"5.80(i)(1)(C)","text":"It is unlawful to use lamprey or any type of shrimp as bait.","kids":0}],"deep":true,"source":"CCR Title 14"},{"code":"5.80(j)","topic":"sturgeon","about":"Sturgeon closure, Yolo Bypass","title":"Inland White Sturgeon","text":"Special Yolo Bypass Flood Control System Sturgeon Closure. It is unlawful to take any sturgeon in the Yolo Bypass, Toe Drain Canal, and Tule Canal upstream of Lisbon Weir at any time.","parts":[],"deep":false,"source":"CCR Title 14"},{"code":"5.81(a)","topic":"sturgeon","about":"Green sturgeon may not be taken","title":"Green Sturgeon","text":"Green sturgeon may not be taken or possessed","parts":[],"deep":false,"source":"CCR Title 14"},{"code":"5.81(b)","topic":"sturgeon","about":"Green sturgeon: removal from water","title":"Green Sturgeon","text":"Green sturgeon may not be removed from the water and shall be released immediately.","parts":[],"deep":false,"source":"CCR Title 14"},{"code":"5.81(c)","topic":"sturgeon","about":"Green sturgeon: reporting","title":"Green Sturgeon","text":"Green sturgeon taken and released incidentally to white sturgeon fishing shall be reported on a Sturgeon Fishing Report Card issued by the department, in accordance with procedures defined in Sections 1.74 and 5.80, Title 14, CCR.","parts":[],"deep":false,"source":"CCR Title 14"},{"code":"5.65(a)","topic":"shad","about":"American shad: open season","title":"Shad, American","text":"Open season: All year, except for closures listed under special regulations.","parts":[],"deep":false,"source":"CCR Title 14"},{"code":"5.65(b)","topic":"shad","about":"American shad: limit","title":"Shad, American","text":"Limit: Twenty-five.","parts":[],"deep":false,"source":"CCR Title 14"},{"code":"5.65(c)","topic":"shad","about":"American shad: methods of take","title":"Shad, American","text":"Methods of take: Shad may be taken only by angling.","parts":[],"deep":false,"source":"CCR Title 14"},{"code":"1.86","topic":"trout","about":"What counts as trout, and that steelhead is one","title":"Trout","text":"Trout Trout includes all trouts, chars, steelhead, and grayling.","parts":[],"deep":false,"source":"CCR Title 14"},{"code":"5.85(a)","topic":"trout","about":"Trout: the statewide seasons and limits, and what overrides them","title":"Trout","text":"General Statewide Regulations:","parts":[{"code":"5.85(a)(1)","text":"All inland lakes and reservoirs; and ponds including those on private lands, are open to fishing all year with a five-trout daily bag limit and 10 trout possession limit.","kids":0},{"code":"5.85(a)(2)","text":"All inland streams, rivers, and canals, except those listed in Sections 7.40(b) and 7.50(b), are open to fishing from the last Saturday in April through November 15 with a five-trout daily bag limit and ten-trout possession limit, with no gear restrictions. From November 16 through the Friday preceding the last Saturday in April, a zero-trout bag limit applies, and only artificial lures with barbless hooks may be used for all species of fish. In waters where the bag limit for trout is zero, trout must be released unharmed and should not be removed from the water.","kids":0},{"code":"5.85(a)(3)","text":"Exceptions:","kids":2},{"code":"5.85(a)(3)(A)","text":"All waters in Section 7.40(b) and Section 7.50(b), Alphabetical List of Trout Waters with Special Fishing Regulations, are those having regulations different from the General Statewide Regulations for trout.","kids":0},{"code":"5.85(a)(3)(B)","text":"Brook Trout bag and possession limits may be taken in addition to the statewide trout daily bag and possession limits. See Section 5.84.","kids":0}],"deep":true,"source":"CCR Title 14"},{"code":"5.88(a)","topic":"trout","about":"Steelhead: report card required","title":"Steelhead Report And Restoration Card Requirements For Inland Waters","text":"Steelhead Fishing Report and Restoration Card Required. All anglers must have a Steelhead Fishing Report and Restoration Card in their possession while fishing for or taking steelhead in anadromous waters, as defined in Section 1.04. Anglers must complete and return the card pursuant to regulations in this Section and in Section 1.74. For purposes of these regulations, a steelhead trout is defined as any rainbow trout greater than 16 inches in length found in anadromous waters.","parts":[],"deep":false,"source":"CCR Title 14"},{"code":"5.88(b)","topic":"trout","about":"Steelhead: recording before you start","title":"Steelhead Report And Restoration Card Requirements For Inland Waters","text":"Prior to beginning fishing activity, the cardholder must record the month, day, and location code on the first available line on the report card.","parts":[],"deep":false,"source":"CCR Title 14"},{"code":"5.88(c)","topic":"trout","about":"Steelhead: recording a fish kept","title":"Steelhead Report And Restoration Card Requirements For Inland Waters","text":"When a hatchery steelhead is retained, the cardholder must immediately mark the appropriate field.","parts":[],"deep":false,"source":"CCR Title 14"},{"code":"5.88(d)","topic":"trout","about":"Steelhead: moving on, or finishing for the day","title":"Steelhead Report And Restoration Card Requirements For Inland Waters","text":"When the cardholder moves to another location code, or finishes fishing for the day, the angler must immediately record on the card the number of wild and hatchery steelhead that were released from that location.","parts":[],"deep":false,"source":"CCR Title 14"},{"code":"5.88(e)","topic":"trout","about":"Steelhead: a card with every line used","title":"Steelhead Report And Restoration Card Requirements For Inland Waters","text":"In the event an angler fills in all lines and returns a Steelhead Fishing Report and Restoration Card, an additional card must be purchased to continue to fish for steelhead. See Section 1.74.","parts":[],"deep":false,"source":"CCR Title 14"},{"code":"5.88(f)","topic":"trout","about":"Steelhead: what the card costs","title":"Steelhead Report And Restoration Card Requirements For Inland Waters","text":"The annual fee for the Steelhead Fishing Report and Restoration Card is specified in Section 7380 of the Fish and Game Code.","parts":[],"deep":false,"source":"CCR Title 14"},{"code":"1.77","topic":"panfish","about":"What counts as sunfish","title":"Sunfish","text":"Sunfish Includes bluegill, green sunfish, redear sunfish, pumpkinseed, warmouth, and Sacramento perch.","parts":[],"deep":false,"source":"CCR Title 14"},{"code":"5.82(a)","topic":"panfish","about":"Sunfish and crappie: open season","title":"Sunfish And Crappie","text":"Open season: All year, except for closures listed under district or special regulations.","parts":[],"deep":false,"source":"CCR Title 14"},{"code":"5.82(b)","topic":"panfish","about":"Sunfish and crappie: limit","title":"Sunfish And Crappie","text":"Limit: Combined bag limit of twenty-five sunfish and crappie of all species, except in:","parts":[{"code":"5.82(b)(1)","text":"Barrett and Upper Otay Lakes (San Diego County): zero bag limit for all species.","kids":0}],"deep":true,"source":"CCR Title 14"},{"code":"5.82(c)","topic":"panfish","about":"Sunfish and crappie: size limit","title":"Sunfish And Crappie","text":"Size Limit: No size limit, except at Hodges and El Capitan Lakes (San Diego County), where the crappie minimum size limit is 10 inches, total length.","parts":[],"deep":false,"source":"CCR Title 14"},{"code":"1.73(a)","topic":"salmon","about":"What counts as salmon","title":"Salmon","text":"Salmon includes Chinook, coho, pink, chum, and sockeye salmon.","parts":[],"deep":false,"source":"CCR Title 14"},{"code":"1.75","topic":"salmon","about":"Salmon spawning areas","title":"Salmon Spawning Areas","text":"Salmon Spawning Areas No salmon may be taken or possessed on any salmon spawning area when it is closed to salmon fishing.","parts":[],"deep":false,"source":"CCR Title 14"}];
